// Batch all per-window list requests into one lexical-ID scan. Sidecars carry
// sorted (ID,count) followed by (position,next rank,predecessor) per occurrence.
#include <algorithm>
#include <cassert>
#include <cstdint>
#include <cstdio>
#include <filesystem>
#include <fstream>
#include <queue>
#include <vector>
using namespace std;namespace fs=std::filesystem;using U=uint32_t;using Q=uint64_t;
Q reads(){ifstream f("/proc/self/io");string k;Q v;while(f>>k>>v)if(k=="read_bytes:")return v;abort();}U get(istream&f){U v;assert(f.read((char*)&v,4));return v;}
int main(int ac,char**av){assert(ac==7);fs::path d=av[1],spill=av[2],side=av[3];U limit=stoul(av[4]);Q n=stoull(av[5]),live=stoull(av[6]),peak=live;assert(live<=2*n&&fs::create_directory(side));auto add=[&](Q x){live+=x;assert(live<=2*n);peak=max(live,peak);};auto req=[&](U w){return side/("req"+to_string(w));};vector<ifstream> requests(limit);vector<ofstream>outputs(limit);using Node=pair<U,U>;priority_queue<Node,vector<Node>,greater<Node>> q;Q request_count=0,sidebytes=0;for(U w=0;w<limit;w++){ifstream f(spill/to_string(w),ios::binary);U r[4];vector<U> ids;while(f.read((char*)r,16)){assert(r[2]&0x7fffffff);f.ignore(r[2]&0x7fffffff);assert(f);if(ids.empty()||ids.back()!=r[0])ids.push_back(r[0]);assert(ids.size()<=1100000);}sort(ids.begin(),ids.end());assert(adjacent_find(ids.begin(),ids.end())==ids.end());ofstream o(req(w),ios::binary);add(4*ids.size());o.write((char*)ids.data(),4*ids.size());o.close();assert(o);request_count+=ids.size();outputs[w].open(side/to_string(w),ios::binary);requests[w].open(req(w),ios::binary);if(ids.size())q.emplace(get(requests[w]),w);assert(reads()<4*n);}ifstream loc(d/"loc.u32",ios::binary),occ(d/"pos-next.u32x2",ios::binary),pred(d/"pred.u8",ios::binary);U k=fs::file_size(d/"loc.u32")/4-1,lo=get(loc);assert(lo==0);vector<U>pairs;vector<char>before;for(U id=0;id<k;id++){U hi=get(loc),ct=hi-lo;assert(lo<hi);if(!q.empty()&&q.top().first==id){assert(ct<=2000000);pairs.resize(2ull*ct);before.resize(ct);occ.seekg(8ull*lo);pred.seekg(lo);assert(occ.read((char*)pairs.data(),8ull*ct)&&pred.read(before.data(),ct));do{auto w=q.top().second;q.pop();auto&o=outputs[w];add(8+9ull*ct);sidebytes+=8+9ull*ct;o.write((char*)&id,4).write((char*)&ct,4).write((char*)pairs.data(),8ull*ct).write(before.data(),ct);assert(o);U next;if(requests[w].read((char*)&next,4)){assert(next>id);q.emplace(next,w);}}while(!q.empty()&&q.top().first==id);}lo=hi;if(!(id%32768))assert(reads()<4*n);}assert(q.empty());for(U w=0;w<limit;w++){outputs[w].close();assert(outputs[w]);requests[w].close();fs::remove(req(w));}assert(reads()<4*n);printf("JOIN windows=%u requests=%llu side_bytes=%llu peak_counted=%llu reads=%llu\n",limit,(unsigned long long)request_count,(unsigned long long)sidebytes,(unsigned long long)peak,(unsigned long long)reads());}
